package com.tenora365.service;
import com.tenora365.entity.*;import com.tenora365.repository.*;import com.tenora365.security.JwtService;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
@Service public class AuthService{final UserRepository users;final RefreshTokenRepository refresh;final OtpTokenRepository otps;final PasswordEncoder enc;final JwtService jwt;final AuditService audit;final long refreshDays;final long otpMinutes;AuthService(UserRepository u,RefreshTokenRepository r,OtpTokenRepository o,PasswordEncoder e,JwtService j,AuditService a,@Value("${app.jwt.refresh-days}")long rd,@Value("${app.otp.minutes}")long om){users=u;refresh=r;otps=o;enc=e;jwt=j;audit=a;refreshDays=rd;otpMinutes=om;}String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public Map<String,Object> login(String username,String password){User u=users.findByUsername(username).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!u.isEnabled()||!enc.matches(password,u.getPasswordHash()))throw new IllegalArgumentException("Invalid credentials");String raw=UUID.randomUUID()+"."+UUID.randomUUID();RefreshToken t=new RefreshToken();t.setUser(u);t.setTokenHash(hash(raw));t.setExpiresAt(Instant.now().plus(refreshDays,java.time.temporal.ChronoUnit.DAYS));refresh.save(t);Map<String,Object> out=new LinkedHashMap<>();out.put("accessToken",jwt.create(u.getId(),u.getSchool()==null?null:u.getSchool().getId(),u.getRole()));out.put("refreshToken",raw);Map<String,Object> me=new LinkedHashMap<>();me.put("id",u.getId());me.put("username",u.getUsername());me.put("name",u.getFullName());me.put("role",u.getRole());me.put("schoolId",u.getSchool()==null?null:u.getSchool().getId());me.put("schoolName",u.getSchool()==null?"TENORA365":u.getSchool().getName());out.put("user",me);return out;}public Map<String,Object> issueFor(User u){String raw=UUID.randomUUID()+"."+UUID.randomUUID();RefreshToken t=new RefreshToken();t.setUser(u);t.setTokenHash(hash(raw));t.setExpiresAt(Instant.now().plus(refreshDays,java.time.temporal.ChronoUnit.DAYS));refresh.save(t);Map<String,Object> out=new LinkedHashMap<>();out.put("accessToken",jwt.create(u.getId(),u.getSchool()==null?null:u.getSchool().getId(),u.getRole()));out.put("refreshToken",raw);return out;}}
